use crate::model::{Summary,Job};
pub fn run(jobs:&[Job], budget: i64) -> Summary {
    let mut order = Vec::new();
    let mut spent = 0i64;
    let mut completed = vec![false; jobs.len()];

    loop {
        let remaining = budget - spent;
        let mut selected: Option<usize> = None;

        for (index, job) in jobs.iter().enumerate() {
            if completed[index] || job.cost > remaining {
                continue;
            }

            let ready = job.deps.iter().all(|dependency| {
                completed[*dependency as usize]
            });
            if ready && selected.map_or(true, |chosen| job.id < jobs[chosen].id) {
                selected = Some(index);
            }
        }

        let Some(index) = selected else { break };
        completed[index] = true;
        spent += jobs[index].cost;
        order.push(jobs[index].id);
    }

    Summary {
        blocked: (jobs.len() - order.len()) as i64,
        order,
        spent,
    }
}

